/** Functional counterparts of common platform widget-library categories. */
public final class LibraryWidgets {
    private LibraryWidgets(){}
    private static final int[] ACTIONS={R.id.widget_action0,R.id.widget_action1,R.id.widget_action2},ROWS={R.id.widget_row0,R.id.widget_row1,R.id.widget_row2},CLOCKS={R.id.tool_clock0,R.id.tool_clock1,R.id.tool_clock2},CITIES={R.id.tool_city0,R.id.tool_city1,R.id.tool_city2},CLOCKROWS={R.id.tool_clockrow0,R.id.tool_clockrow1,R.id.tool_clockrow2};
    public static final String[] TOOL_KEYS={"wifi","bluetooth","display","sound","location","battery","calculator","camera"},TOOL_NAMES={"Wi-Fi","Bluetooth","Display","Sound","Location","Battery","Calculator","Camera"};
    public static String contactLabel(JSONObject config,int n){String name=config.optString("name"+n,"").trim();return name.isEmpty()?(config.optString("phone"+n,"").isEmpty()?"+ Add":"Favorite "+(n+1)):name;}
    public static String[] variants(String kind){return switch(kind){case "battery"->new String[]{"Charge ring","Percentage and details"};case "calendar"->new String[]{"Month grid","This week"};case "agenda"->new String[]{"Next 7 days","Next 30 days"};case "weather"->new String[]{"Current conditions","Three-day forecast"};case "photos"->new String[]{"Crop to frame","Fit whole photo"};case "worldclock"->new String[]{"Three cities","One city"};case "countdown"->new String[]{"Days until the date","Count days after the date too"};case "contacts"->new String[]{"Three favorites","One favorite"};case "search"->new String[]{"Google","DuckDuckGo","Bing"};case "controls"->new String[]{"Connections","Everyday apps"};default->new String[]{"Artwork and controls","Simple player"};};}
    public static PendingIntent configure(Context c,int id,String kind){return PendingIntent.getActivity(c,0,new Intent(c,WidgetConfigActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).putExtra("kind",kind).setData(Uri.parse("nook://configure/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static PendingIntent activity(Context c,String action,int id,String value){return PendingIntent.getActivity(c,0,WidgetUtilityActivity.intent(c,action,id,value),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static PendingIntent broadcast(Context c,String action,int id,String value){return PendingIntent.getBroadcast(c,0,new Intent(c,WidgetActionReceiver.class).setAction(action).putExtra("widget",id).putExtra("value",value).setData(Uri.parse("nook://library/"+id+"/"+action+"/"+value)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static void hide(RemoteViews v,int... ids){for(int id:ids)v.setViewVisibility(id,View.GONE);}
    private static void actions(RemoteViews v,String[] labels,PendingIntent[] clicks){v.setViewVisibility(R.id.widget_actions,View.VISIBLE);for(int n=0;n<3;n++){v.setTextViewText(ACTIONS[n],labels[n]);if(clicks!=null&&clicks[n]!=null)v.setOnClickPendingIntent(ACTIONS[n],clicks[n]);}}
    private static void visual(RemoteViews v,Bitmap bitmap,String description){if(bitmap==null)return;v.setViewVisibility(R.id.tool_visual,View.VISIBLE);v.setImageViewBitmap(R.id.tool_visual,bitmap);v.setContentDescription(R.id.tool_visual,description);}
    private static Bitmap calendar(Context c,JSONObject config,boolean week){
        int width=600,height=week?140:320;Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);WidgetDesign.Colors colors=WidgetDesign.colors(config,"calendar");paint.setTypeface(WidgetDesign.typeface(c,config,false));paint.setTextAlign(Paint.Align.CENTER);
        DayOfWeek start=config.optBoolean("sunday",false)?DayOfWeek.SUNDAY:DayOfWeek.MONDAY;LocalDate today=LocalDate.now(),first=week?today.with(TemporalAdjusters.previousOrSame(start)):today.withDayOfMonth(1).with(TemporalAdjusters.previousOrSame(start));
        Set<LocalDate> events=new HashSet<>();for(WidgetData.Event e:WidgetData.events(c,first.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli(),first.plusDays(42).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli()))events.add(WidgetData.eventDay(e));
        for(int col=0;col<7;col++){paint.setTextSize(22);paint.setColor(colors.muted);canvas.drawText(new String[]{"M","T","W","T","F","S","S"}[(col+(start==DayOfWeek.SUNDAY?6:0))%7],(col+.5f)*width/7,26,paint);}
        int count=week?7:42;float rowHeight=week?88:45;for(int n=0;n<count;n++){LocalDate date=first.plusDays(n);float x=(n%7+.5f)*width/7,y=54+(n/7)*rowHeight;boolean selected=date.equals(today);if(selected){paint.setColor(colors.accent);canvas.drawCircle(x,y+12,week?31:20,paint);}paint.setColor(selected?contrast(colors.accent):date.getMonth()==today.getMonth()?colors.text:colors.muted);paint.setTextSize(week?34:25);canvas.drawText(String.valueOf(date.getDayOfMonth()),x,y+21,paint);if(events.contains(date)){paint.setColor(selected?contrast(colors.accent):colors.accent);canvas.drawCircle(x,y+34,2.5f,paint);}}return bitmap;
    }
    private static int contrast(int color){return Color.luminance(color)>.45?0xff16191b:Color.WHITE;}
    private static Bitmap battery(Context c,JSONObject config,int percent){
        Bitmap bitmap=Bitmap.createBitmap(600,270,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);WidgetDesign.Colors colors=WidgetDesign.colors(config,"battery");RectF ring=new RectF(190,20,410,240);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(20);paint.setStrokeCap(Paint.Cap.ROUND);paint.setColor(colors.chip);canvas.drawOval(ring,paint);paint.setColor(colors.accent);canvas.drawArc(ring,-90,Math.max(0,percent)*3.6f,false,paint);paint.setStyle(Paint.Style.FILL);paint.setTypeface(WidgetDesign.typeface(c,config,true));paint.setTextSize(70);paint.setTextAlign(Paint.Align.CENTER);paint.setColor(colors.text);canvas.drawText(percent<0?"—":percent+"%",300,151,paint);return bitmap;
    }
    private static Bitmap weather(Context c,JSONObject config,JSONObject data){
        Bitmap bitmap=Bitmap.createBitmap(600,145,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);WidgetDesign.Colors colors=WidgetDesign.colors(config,"weather");paint.setTypeface(WidgetDesign.typeface(c,config,false));paint.setTextAlign(Paint.Align.CENTER);JSONObject days=data.optJSONObject("daily");if(days==null)return bitmap;
        JSONArray dates=days.optJSONArray("time"),high=days.optJSONArray("temperature_2m_max"),low=days.optJSONArray("temperature_2m_min");if(dates==null||high==null||low==null)return bitmap;
        for(int n=0;n<Math.min(3,dates.length());n++){float x=100+n*200;paint.setColor(colors.chip);canvas.drawRoundRect(x-88,6,x+88,137,22,22,paint);paint.setColor(colors.muted);paint.setTextSize(24);String day;try{day=LocalDate.parse(dates.getString(n)).format(DateTimeFormatter.ofPattern("EEE"));}catch(Exception e){day="Day "+(n+1);}canvas.drawText(day,x,47,paint);paint.setColor(colors.text);paint.setTextSize(28);canvas.drawText(WeatherData.degrees(high.optDouble(n),config)+" / "+WeatherData.degrees(low.optDouble(n),config),x,99,paint);}return bitmap;
    }
    private static Bitmap record(Context c,JSONObject config){Bitmap bitmap=Bitmap.createBitmap(600,240,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint p=new Paint(3);WidgetDesign.Colors colors=WidgetDesign.colors(config,"music");p.setColor(colors.chip);canvas.drawCircle(300,120,110,p);p.setColor(colors.accent);canvas.drawCircle(300,120,42,p);p.setColor(colors.surface);canvas.drawCircle(300,120,10,p);return bitmap;}
    public static RemoteViews render(Context c,int id,String kind,JSONObject config,boolean small,boolean preview){
        boolean compact=small||config.optInt("density",0)==1;int variant=config.optInt("variant",0);String layout=kind.equals("search")&&ReplicaDesign.enabled(config)?"replica_search":kind.equals("music")&&ReplicaDesign.enabled(config)?"replica_music":(kind.equals("photos")&&(variant==0||ReplicaDesign.enabled(config))?"widget_photo":"widget_tools")+(compact?"_compact":"");RemoteViews v=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,layout,config));
        hide(v,R.id.tool_visual,R.id.tool_clocks,R.id.widget_meta,R.id.widget_actions,R.id.widget_progress,R.id.widget_time,R.id.widget_date,R.id.widget_row0,R.id.widget_row1,R.id.widget_row2);
        v.setViewVisibility(R.id.widget_title,View.VISIBLE);v.setViewVisibility(R.id.widget_body,View.VISIBLE);v.setImageViewResource(R.id.tool_visual,0);
        for(int row:CLOCKROWS)v.setViewVisibility(row,View.VISIBLE);
        WidgetDesign.Colors colors=WidgetDesign.colors(config,kind);v.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,kind));v.setImageViewResource(R.id.widget_icon,Widgets.iconResource(kind));v.setTextViewText(R.id.widget_label,Widgets.title(kind).toUpperCase(Locale.ROOT));v.setTextViewText(R.id.widget_title,"");v.setTextViewText(R.id.widget_body,"");
        for(int n=0;n<3;n++)v.setImageViewResource(Widgets.BACKGROUND_IMAGES[n+1],Widgets.chipResource(config,kind));for(int image:Widgets.BACKGROUND_IMAGES)v.setInt(image,"setImageAlpha",Widgets.surfaceAlpha(config));
        for(int text:new int[]{R.id.widget_label,R.id.widget_settings,R.id.widget_title,R.id.widget_time,R.id.widget_row0,R.id.widget_row1,R.id.widget_row2,R.id.widget_action0,R.id.widget_action1,R.id.widget_action2})v.setTextColor(text,colors.text);for(int text:new int[]{R.id.widget_body,R.id.widget_meta,R.id.widget_date})v.setTextColor(text,colors.muted);
        PendingIntent setup=configure(c,id,kind);if(!preview){v.setOnClickPendingIntent(R.id.widget_settings,setup);v.setOnClickPendingIntent(R.id.widget_root,setup);}
        if(kind.equals("battery")){
            WidgetData.Battery battery=WidgetData.battery(c);v.setTextViewText(R.id.widget_title,variant==1?(battery.percent<0?"Unavailable":battery.percent+"%"):"Phone battery");v.setTextViewText(R.id.widget_body,battery.source+(variant==1&&!Float.isNaN(battery.temperature)?" · "+String.format(Locale.getDefault(),"%.1f°C",battery.temperature):""));if(variant==0){hide(v,R.id.widget_title);visual(v,ReplicaDesign.enabled(config)?ReplicaDesign.battery(c,config,battery):battery(c,config,battery.percent),"Phone battery "+battery.percent+" percent");}if(!preview)v.setOnClickPendingIntent(R.id.widget_root,broadcast(c,"library_refresh",id,""));
        }else if(kind.equals("calendar")){
            boolean week=compact||variant==1;v.setTextViewText(R.id.widget_title,LocalDate.now().format(DateTimeFormatter.ofPattern("MMMM yyyy")));hide(v,R.id.widget_body);visual(v,ReplicaDesign.enabled(config)?ReplicaDesign.calendar(c,config,week):calendar(c,config,week),week?"Current week, today highlighted":"Current month, today highlighted");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,activity(c,"calendar",id,""));
        }else if(kind.equals("agenda")){
            if(!WidgetData.calendarAllowed(c)){v.setTextViewText(R.id.widget_title,"Connect your calendar");v.setTextViewText(R.id.widget_body,"Read-only access shows upcoming events here.");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,activity(c,"calendar_access",id,""));}
            else{List<WidgetData.Event> events=WidgetData.events(c,System.currentTimeMillis(),System.currentTimeMillis()+(variant==0?7L:30L)*86400000);v.setTextViewText(R.id.widget_title,events.isEmpty()?"A little breathing room.":"Coming up");v.setTextViewText(R.id.widget_body,events.isEmpty()?"No events in the selected period.":"");for(int n=0;n<Math.min(compact?1:3,events.size());n++){WidgetData.Event event=events.get(n);v.setViewVisibility(ROWS[n],View.VISIBLE);v.setTextViewText(ROWS[n],event.title+" · "+(event.allDay?WidgetData.eventDay(event).format(DateTimeFormatter.ofPattern("d MMM"))+" · All day":Widgets.when(event.begin)));if(!preview)v.setOnClickPendingIntent(ROWS[n],activity(c,"event",id,String.valueOf(event.id)));}if(!preview)v.setOnClickPendingIntent(R.id.widget_root,activity(c,"calendar",id,""));if(!events.isEmpty())hide(v,R.id.widget_title,R.id.widget_body);}
        }else if(kind.equals("weather")){
            JSONObject data=WeatherData.cached(c,config),current=data.optJSONObject("current");if(!WeatherData.configured(config)){v.setTextViewText(R.id.widget_title,"Choose your city");v.setTextViewText(R.id.widget_body,"City-based weather. No location permission needed.");}
            else if(current==null){v.setTextViewText(R.id.widget_title,config.optString("city","Weather"));v.setTextViewText(R.id.widget_body,(WeatherData.failed(c,config)?"Offline · Tap to retry":"Tap to load weather")+" · Open-Meteo");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,broadcast(c,"library_refresh",id,""));}
            else{v.setTextViewText(R.id.widget_title,WeatherData.temperature(current.optDouble("temperature_2m"),config)+"°"+(config.optBoolean("fahrenheit",false)?"F":"C")+" · "+config.optString("city","Weather"));v.setTextViewText(R.id.widget_body,(WeatherData.failed(c,config)||System.currentTimeMillis()-data.optLong("fetchedAt")>7200000?"Cached · ":"")+WeatherData.condition(current.optInt("weather_code",-1))+(current.isNull("apparent_temperature")?"":" · Feels "+WeatherData.temperature(current.optDouble("apparent_temperature"),config)+"°"));if(variant==1&&!compact)visual(v,weather(c,config,data),"Three-day high and low temperatures");if(!compact){v.setViewVisibility(R.id.widget_meta,View.VISIBLE);v.setTextViewText(R.id.widget_meta,(WeatherData.failed(c,config)?"Offline cache · ":"Synced ")+java.time.Instant.ofEpochMilli(data.optLong("fetchedAt")).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("d MMM, HH:mm"))+" · Open-Meteo");}if(!preview)v.setOnClickPendingIntent(R.id.widget_root,broadcast(c,"library_refresh",id,""));}
        }else if(kind.equals("photos")){
            Bitmap photo=WidgetData.photo(c,config.optString("photoUri",""));if(photo==null){v.setTextViewText(R.id.widget_title,"A photo worth keeping");v.setTextViewText(R.id.widget_body,"Choose a photo in widget options.");}else{hide(v,R.id.widget_body);String caption=config.optString("caption","");v.setTextViewText(R.id.widget_title,caption);if(caption.isEmpty())hide(v,R.id.widget_title);visual(v,ReplicaDesign.enabled(config)?ReplicaDesign.photo(c,id,config,photo):photo,caption.isEmpty()?"Selected photo":caption);if(!preview)v.setOnClickPendingIntent(R.id.widget_root,activity(c,"photo",id,config.optString("photoUri")));}
        }else if(kind.equals("worldclock")){
            hide(v,R.id.widget_body);v.setTextViewText(R.id.widget_title,"Time around you");if(compact)hide(v,R.id.widget_title);v.setViewVisibility(R.id.tool_clocks,View.VISIBLE);String[] defaults={TimeZone.getDefault().getID(),"UTC","America/New_York"};
            for(int n=0;n<3;n++){if((compact||variant==1)&&n>0){v.setViewVisibility(CLOCKROWS[n],View.GONE);continue;}String zone=config.optString("zone"+n,defaults[n]);try{ZoneId.of(zone);}catch(Exception e){zone=defaults[n];}v.setTextViewText(CITIES[n],LibraryOptions.cityName(zone));v.setTextColor(CITIES[n],colors.muted);v.setTextColor(CLOCKS[n],colors.text);v.setString(CLOCKS[n],"setTimeZone",zone);String format=config.optBoolean("clock24",true)?"HH:mm":"h:mm a";v.setCharSequence(CLOCKS[n],"setFormat12Hour",format);v.setCharSequence(CLOCKS[n],"setFormat24Hour",format);v.setTextViewTextSize(CLOCKS[n],TypedValue.COMPLEX_UNIT_SP,22*WidgetDesign.scale(config));}
        }else if(kind.equals("countdown")){
            LocalDate target=WidgetData.targetDay(config);if(target==null){v.setTextViewText(R.id.widget_title,"Something to look forward to");v.setTextViewText(R.id.widget_body,"Choose an occasion and date in widget options.");}else{long days=java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),target);v.setTextViewText(R.id.widget_title,days>0?days+" days to go":days==0?"Today’s the day":variant==1?Math.abs(days)+" days since":"The date has arrived");v.setTextViewText(R.id.widget_body,config.optString("occasion","Your occasion")+" · "+target.format(DateTimeFormatter.ofPattern("d MMM yyyy")));}
        }else if(kind.equals("contacts")){
            v.setTextViewText(R.id.widget_title,"Your people");v.setTextViewText(R.id.widget_body,"Tap a favorite to open the dialer.");String[] labels=new String[3];PendingIntent[] clicks=new PendingIntent[3];for(int n=0;n<3;n++){String phone=config.optString("phone"+n,"");labels[n]=contactLabel(config,n);clicks[n]=preview?null:phone.isEmpty()?setup:activity(c,"dial",id,phone);}actions(v,labels,clicks);if(compact)hide(v,R.id.widget_body,R.id.widget_title);if(variant==1){v.setViewVisibility(R.id.widget_title,View.VISIBLE);v.setViewVisibility(R.id.widget_body,View.VISIBLE);v.setTextViewText(R.id.widget_title,labels[0]);v.setTextViewText(R.id.widget_body,config.optString("phone0","Choose a favorite"));hide(v,R.id.widget_actions);if(!preview)v.setOnClickPendingIntent(R.id.widget_root,clicks[0]);}
        }else if(kind.equals("search")){
            v.setTextViewText(R.id.widget_title,"Search the web");v.setTextViewText(R.id.widget_body,"Your next idea starts here.");actions(v,new String[]{"Search","Voice","Options"},preview?null:new PendingIntent[]{activity(c,"search",id,String.valueOf(variant)),activity(c,"voice_search",id,String.valueOf(variant)),setup});if(compact)hide(v,R.id.widget_body,R.id.widget_title);if(!preview)v.setOnClickPendingIntent(R.id.widget_root,activity(c,"search",id,String.valueOf(variant)));
        }else if(kind.equals("controls")){
            v.setTextViewText(R.id.widget_title,"Little shortcuts");v.setTextViewText(R.id.widget_body,"Open a settings panel or a favorite app.");String[] labels=new String[3];PendingIntent[] clicks=new PendingIntent[3];for(int n=0;n<3;n++){int slot=WidgetDesign.clamp(config.optInt("control"+n,variant==0?n:new int[]{6,7,5}[n]),0,TOOL_KEYS.length-1);labels[n]=TOOL_NAMES[slot];clicks[n]=preview?null:activity(c,"tool",id,TOOL_KEYS[slot]);}actions(v,labels,clicks);if(compact)hide(v,R.id.widget_title,R.id.widget_body);
        }else if(kind.equals("music")){
            MediaController controller=MediaAccess.controller(c);if(!MediaAccess.allowed(c)){v.setTextViewText(R.id.widget_title,"Connect your music");v.setTextViewText(R.id.widget_body,"Enable media access to use your active player.");if(!preview)v.setOnClickPendingIntent(R.id.widget_root,activity(c,"media_access",id,""));}
            else if(controller==null){v.setTextViewText(R.id.widget_title,"Ready when you are");v.setTextViewText(R.id.widget_body,"Start playback in a compatible music or podcast app.");}
            else{if(!preview&&controller.getSessionActivity()!=null)v.setOnClickPendingIntent(R.id.widget_root,controller.getSessionActivity());MediaMetadata metadata=controller.getMetadata();String title=metadata==null?null:metadata.getString(MediaMetadata.METADATA_KEY_TITLE),artist=metadata==null?null:metadata.getString(MediaMetadata.METADATA_KEY_ARTIST);v.setTextViewText(R.id.widget_title,title==null?"Now playing":title);v.setTextViewText(R.id.widget_body,artist==null?"Active media player":artist);PlaybackState state=controller.getPlaybackState();boolean playing=state!=null&&state.getState()==PlaybackState.STATE_PLAYING;actions(v,new String[]{"‹ Prev",playing?"Pause":"Play","Next ›"},preview?null:new PendingIntent[]{broadcast(c,"media",id,"previous"),broadcast(c,"media",id,"toggle"),broadcast(c,"media",id,"next")});Bitmap art=metadata==null?null:metadata.getBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART);if(art==null&&metadata!=null)art=metadata.getBitmap(MediaMetadata.METADATA_KEY_ART);if(!compact&&variant==0){if(art!=null){float scale=Math.min(1,500f/Math.max(art.getWidth(),art.getHeight()));visual(v,Bitmap.createScaledBitmap(art,Math.max(1,(int)(art.getWidth()*scale)),Math.max(1,(int)(art.getHeight()*scale)),true),"Album artwork");}else visual(v,record(c,config),"Media record illustration");}if(compact)hide(v,R.id.widget_body);}
        }
        WidgetDesign.surfaces(c,v,id,kind,config,compact,new int[]{R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2});WidgetDesign.dedicated(c,v,id,kind,config,compact);
        if(kind.equals("countdown")){LocalDate target=WidgetData.targetDay(config);if(target!=null){long days=java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),target);if(days>=0||variant==1){String occasion=config.optString("occasion","").trim();if(occasion.isEmpty())occasion="Your occasion";v.setTextViewText(R.id.widget_title,String.valueOf(Math.abs(days)));v.setTextViewText(R.id.widget_body,(days>0?"days to go":days==0?"today":"days since")+" · "+occasion+"\n"+target.format(DateTimeFormatter.ofPattern("d MMM yyyy")));v.setTextViewTextSize(R.id.widget_title,TypedValue.COMPLEX_UNIT_SP,(compact?42:60)*WidgetDesign.scale(config));}}}
        if(kind.equals("battery")&&variant==1)v.setTextViewTextSize(R.id.widget_title,TypedValue.COMPLEX_UNIT_SP,(compact?42:54)*WidgetDesign.scale(config));
        if(compact){v.setInt(R.id.widget_title,"setMaxLines",1);v.setInt(R.id.widget_body,"setMaxLines",1);}else v.setInt(R.id.widget_body,"setMaxLines",2);ReplicaDesign.library(c,v,kind,config,compact);return v;
    }
}
